 // Twisted notched rotor core. Bars sit in actual outer notches.
 function coreGeometry(length=.574,skew=.13,offset=0){const contour=[];for(let i=0;i<40;i++){const a=i*TAU/40;for(const [da,r] of [[-.016,.299],[-.013,.289],[.013,.289],[.016,.299],[.039,.299],[.063,.299],[.086,.299],[.110,.299]])contour.push(new THREE.Vector2(r*Math.cos(a+da),r*Math.sin(a+da)));}const hole=Array.from({length:64},(_,i)=>new THREE.Vector2(.047*Math.cos(-i*TAU/64),.047*Math.sin(-i*TAU/64)));const points=[...contour,...hole],n=points.length,slices=12,vertices=[],indices=[];for(let j=0;j<=slices;j++){const a=offset+skew*j/slices,c=Math.cos(a),s=Math.sin(a);for(const p of points)vertices.push(p.x*c-p.y*s,p.x*s+p.y*c,-length/2+j*length/slices);}for(let j=0;j<slices;j++){for(const [start,size] of [[0,contour.length],[contour.length,hole.length]])for(let i=0;i<size;i++){const a=j*n+start+i,b=j*n+start+(i+1)%size,c=a+n,d=b+n;indices.push(a,b,d,a,d,c);}}for(const tri of THREE.ShapeUtils.triangulateShape(contour,[hole])){indices.push(tri[2],tri[1],tri[0],...tri.map(i=>i+slices*n));}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));g.setIndex(indices);g.computeVertexNormals();return g;}
 const rotor=part('rotor',.85,1.53);const rotorSpin=new THREE.Group();rotor.group.add(rotorSpin);add(rotor,coreGeometry(),colors.rotor,0,0,0,rotorSpin);for(let i=0;i<40;i++)ring(rotor,.287,.047,.0008,-.282+i*.0145,colors.dark,[],rotorSpin,'lamination');ring(rotor,.110,.047,.030,-.302,colors.steel,[],rotorSpin);ring(rotor,.110,.047,.030,.302,colors.steel,[],rotorSpin);motions.push({object:rotorSpin,ratio:1});
