 const shaft=part('shaft',.105,1.9);const shaftSpin=new THREE.Group();shaft.group.add(shaftSpin);add(shaft,cylinder(.046,.046,2.545),colors.steel,0,0,-.0375,shaftSpin);add(shaft,cylinder(.052,.052,.14),colors.steel,0,0,.745,shaftSpin);for(const z of [.40,1.04])ring(shaft,.060,.046,.020,z,colors.steel,[],shaftSpin);for(let i=0;i<18;i++)boxAt(shaft,[.001,.006,.12],.0465,i*TAU/18,-1.22,shaftSpin,colors.steel);motions.push({object:shaftSpin,ratio:1});
